export const quoteCatalogList = Object.values(quoteCatalogBySlug);

export function getLocalizedQuoteEntry(entry: QuoteCatalogEntry, locale: "en" | "ms" | "zh"): QuoteCatalogEntry {
  if (locale === "en") return entry;
  const override = entry.i18n?.[locale];
  if (!override) return entry;
  return {
    ...entry,
    title: override.title || entry.title,
    tagline: override.tagline || entry.tagline,
    warranty: override.warranty || entry.warranty,
    subServices: override.subServices?.length ? override.subServices : entry.subServices,
  };
}
